    "whereItWorks": "\u0644\u06cc \u06a9\u0648 \u062e\u06d5\u0628\u0627\u062a\u06ce \u062f\u06cc\u06a9\u06d5",
    "customersCanEarnStampsAtTheActiveLocationsSelectedHere": "\u062e\u06d5\u0631\u06cc\u062f\u0627\u0631 \u062f\u06cc\u06a9\u0627\u0631\u06cc\u0646 \u0644\u06cc \u062c\u06cc\u0647\u06ce\u0646 \u0686\u0627\u0644\u0627\u06a9 \u06ce\u0646 \u06a9\u0648 \u0644\u06cc \u06a4\u06cc\u0631 \u0647\u0627\u062a\u06cc\u0646\u06d5 \u0647\u06cc\u0644\u0628\u06cc\u0698\u0627\u0631\u062a\u06cc\u0646 \u0645\u06c6\u0647\u0631\u0627 \u062e\u0648\u06d5 \u0628\u06cc\u062f\u06cc\u0646.",
    "createAnUpdateToMakeChanges": "\u0698\u06cc \u0628\u06c6 \u06af\u0648\u0647\u06d5\u0631\u062a\u06cc\u0646\u0627\u0646 \u0646\u0648\u06a4\u06d5\u06a9\u06cc\u0631\u06cc\u0646\u06d5\u06a9 \u0686\u06ce\u0628\u06cc\u06a9\u06cc\u0646",
    "theLiveCardStaysUnchangedUntilYouReviewAndPublishTheUpdate": "\u0647\u06d5\u06cc\u0627 \u06a9\u0648 \u0647\u0648\u0646 \u0646\u0648\u06a4\u06d5\u06a9\u06cc\u0631\u06cc\u0646\u06ce \u0628\u06cc\u0646\u06cc\u0631\u062e\u06cc\u0646\u06cc\u0646 \u0648 \u0628\u06cc\u0648\u06d5\u0634\u06cc\u0646\u06cc\u0646, \u0642\u06d5\u0631\u062a\u0627 \u0632\u06cc\u0646\u062f\u06cc \u0646\u0627\u06cc\u06ce \u06af\u0648\u0647\u06d5\u0631\u062a\u06cc\u0646.",
    "createUpdate": "\u0646\u0648\u06a4\u06d5\u06a9\u06cc\u0631\u06cc\u0646 \u0628\u06cc\u0627\u0641\u06cc\u0631\u06cc\u0646\u06d5",
