    "proMultipleRewardsMilestonesPathAndRingRequireGrowthOrScale": "\u067e\u0631\u06c6, \u062e\u06d5\u0644\u0627\u062a\u06ce\u0646 \u067e\u06cc\u0631\u0698\u06cc\u0645\u0627\u0631, \u0645\u06cc\u0644\u06cc\u062a\u0627\u0646, \u0631\u06ce, \u0648 \u0631\u06cc\u0646\u06af \u0645\u06d5\u0632\u06cc\u0646\u0628\u0648\u0646 \u0627\u0646 \u067e\u06cc\u06a4\u0627\u0646 \u0647\u06d5\u0648\u062c\u06d5 \u062f\u06cc\u06a9\u06d5.",
