    "requiredStampCount": "\u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u0645\u06c6\u0647\u0631\u0627 \u067e\u06ce\u0648\u06cc\u0633\u062a",
    "earningDescription": "\u062f\u0627\u0646\u0627\u0633\u06cc\u0646\u0627 \u0642\u06d5\u0632\u06d5\u0646\u062c\u06a9\u06cc\u0631\u06cc\u0646\u06ce",
    "operationsPolicy": "\u067e\u06c6\u0644\u06cc\u062a\u06cc\u06a9\u0627\u06cc\u0627 \u06c6\u067e\u06d5\u0631\u0627\u0633\u06cc\u06c6\u0646\u06ce\u0646",
    "operationLimitsDailyCapsPurchasePolicyAndResetBehaviorFollowTheSetupEachCustomerJoinedUnder": "\u0633\u06cc\u0646\u06c6\u0631\u06ce\u0646 \u062e\u06d5\u0628\u06cc\u062a\u0627\u0646\u062f\u06cc\u0646\u06ce, \u0633\u06d5\u0631\u0645\u0627\u06cc\u06ce\u0646 \u0631\u06c6\u0698\u0627\u0646\u06d5, \u067e\u06c6\u0644\u06cc\u062a\u06cc\u06a9\u0627\u06cc\u0627 \u06a9\u06cc\u0631\u06cc\u0646\u06ce, \u0648 \u0628\u06d5\u0647\u0631\u06d5\u0645\u06d5\u0646\u062f\u06cc\u06cc\u0627 \u06a4\u06d5\u0633\u0627\u0632\u06a9\u06cc\u0631\u06cc\u0646\u06ce \u0644\u06cc \u067e\u06d5\u06cc \u0633\u0627\u0632\u06a9\u06cc\u0631\u06cc\u0646\u0627 \u06a9\u0648 \u0647\u06d5\u0631 \u062e\u06d5\u0631\u06cc\u062f\u0627\u0631 \u062a\u06ce \u062f\u06d5 \u0628\u06d5\u0634\u062f\u0627\u0631 \u0628\u0648\u06cc\u06d5.",
