    "descriptiveRewardsAndMilestones": "\u062e\u06d5\u0644\u0627\u062a \u0648 \u0642\u06c6\u0646\u0627\u062e\u06ce\u0646 \u062f\u06cc\u06cc\u0627\u0631\u06a9\u06d5\u0631",
    "thresholdsMustBeUniqueAndOneFinalRewardMustSitAtTheGoal": "\u067e\u06ce\u062f\u06cc\u06a4\u06cc \u06cc\u06d5 \u06a9\u0648 \u0628\u06d5\u0646\u062f \u06cc\u06d5\u06a9\u062a\u0627 \u0628\u06cc\u0646 \u0648 \u06cc\u06d5\u06a9 \u062e\u06d5\u0644\u0627\u062a\u0627 \u067e\u0627\u0634\u06cc\u0646 \u062f\u06cc\u06a4\u06ce \u0644\u06cc \u0633\u06d5\u0631 \u0627\u0631\u0645\u0627\u0646\u062c\u06ce \u0631\u0648\u0646\u06d5.",
    "addMilestone": "\u0645\u06cc\u0644\u06cc\u06c6\u0646\u06ce \u0632\u06ce\u062f\u06d5 \u0628\u06cc\u06a9\u06cc\u0646",
