    "redemptionsPerEarnedReward": "\u0631\u06d5\u062f\u06d5\u067e\u062a\u06cc\u06c6\u0646\u0633 \u067e\u06d5\u0631 \u062e\u06d5\u0644\u0627\u062a\u0627 \u0642\u06d5\u0632\u06d5\u0646\u062c\u06a9\u06cc\u0631\u06cc",
