    "newRulesApplyToCustomersWhoJoinAfterThisUpdateIsPublishedExistingCustomersKeepTheirCurrentTerms": "\u0631\u06ce\u06af\u06d5\u0632\u06ce\u0646 \u0646\u0648 \u0698\u06cc \u0628\u06c6 \u062e\u06d5\u0631\u06cc\u062f\u0627\u0631\u06ce\u0646 \u06a9\u0648 \u067e\u06cc\u0634\u062a\u06cc \u0648\u06d5\u0634\u0627\u0646\u062f\u06cc\u0646\u0627 \u06a4\u06ce \u0646\u0648\u06a4\u06d5\u06a9\u06cc\u0631\u06cc\u0646\u06ce \u062a\u06d5\u06a4\u0644\u06ce \u062f\u06cc\u0628\u06cc\u0646 \u062f\u06d5\u0631\u0628\u0627\u0633 \u062f\u06cc\u0628\u06cc\u0646. \u062e\u06d5\u0631\u06cc\u062f\u0627\u0631\u06ce\u0646 \u0647\u06d5\u06cc\u06cc \u0634\u06d5\u0631\u062a\u06ce\u0646 \u062e\u0648\u06d5 \u06cc\u06ce\u0646 \u0647\u06d5\u06cc\u06cc \u062f\u06cc\u067e\u0627\u0631\u06ce\u0632\u06cc\u0646.",
