    "controlsDailyLimitsReportingDaysAndRewardExpiryDates": "\u0633\u06cc\u0646\u06c6\u0631\u06ce\u0646 \u0631\u06c6\u0698\u0627\u0646\u06d5, \u0631\u06c6\u0698\u06ce\u0646 \u0631\u0627\u067e\u06c6\u0631\u06ce, \u0648 \u062a\u0627\u0631\u06cc\u062e\u06ce\u0646 \u0642\u06d5\u062f\u0627\u0646\u062f\u06cc\u0646\u0627 \u062e\u06d5\u0644\u0627\u062a\u06ce \u06a9\u06c6\u0646\u062a\u0631\u06c6\u0644 \u062f\u06cc\u06a9\u06d5.",
