    "setADailyLimitPerCustomer": "\u0698\u06cc \u0647\u06d5\u0631 \u062e\u06d5\u0631\u06cc\u062f\u0627\u0631 \u0631\u06d5 \u0633\u06cc\u0646\u06c6\u0631\u06d5\u06a9 \u0631\u06c6\u0698\u0627\u0646\u06d5 \u0628\u06cc\u062c\u06cc\u0647 \u0628\u06cc\u06a9\u06cc\u0646",
