    "requireAMinimumPurchase": "\u06a9\u06cc\u0631\u06cc\u0646\u06d5\u06a9 \u0647\u06cc\u0646\u062f\u06cc\u06a9\u062a\u06cc\u0631\u06cc\u0646 \u0647\u06d5\u0648\u062c\u06d5 \u062f\u06cc\u06a9\u06d5",
