    "aNewerChangeWasSavedElsewhereWafloWillNotOverwriteEitherSetOfEditsAutomatically": "\u06af\u0648\u0647\u06d5\u0631\u06cc\u0646\u06d5\u06a9 \u0646\u0648\u062a\u06cc\u0631 \u0644\u06cc \u062c\u06cc\u0647\u06d5\u06a9 \u062f\u06cc\u0646 \u0647\u0627\u062a\u06d5 \u062e\u06cc\u0644\u0627\u0633 \u06a9\u06cc\u0631\u06cc\u0646. \u0648\u0627\u0641\u0644\u06c6 \u062f\u06ce \u0647\u06d5\u0631 \u062f\u0648 \u06a9\u06c6\u0645\u06d5\u06a9 \u06af\u0648\u0647\u06d5\u0631\u062a\u06c6\u06cc\u0627\u0646 \u0628\u06cc\u062e\u0648\u06d5\u0628\u06d5\u0631 \u0646\u06d5\u0646\u06cc\u06a4\u06cc\u0633\u06d5.",
    "keepACopyOfYourEditsThenLoadTheLatestCardOrDeliberatelyReapplyYours": "\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9 \u06af\u0648\u0647\u06d5\u0631\u0627\u0646\u062f\u06cc\u0646\u06ce\u0646 \u062e\u0648\u06d5 \u0628\u06cc\u0647\u06ce\u0644\u06cc\u0646, \u062f\u0648\u06a4 \u0631\u06d5 \u0642\u06d5\u0631\u062a\u0627 \u0647\u06d5\u0631\u06cc \u067e\u0627\u0634\u06cc\u0646 \u0628\u0627\u0631 \u0628\u06cc\u06a9\u06cc\u0646 \u0627\u0646 \u0698\u06cc \u0628\u06cc \u0642\u06d5\u0633\u062a\u06cc \u06cc\u0627 \u062e\u0648\u06d5 \u0698\u06cc \u0646\u0648 \u06a4\u06d5 \u0628\u06cc\u062c\u06cc\u0647 \u0628\u06cc\u06a9\u06cc\u0646.",
