    "viewChangeHistory": "\u0628\u06cc\u0646\u06cc\u0646\u06cc \u0645\u06ce\u0698\u0648\u0648\u06cc \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646",
    "manageLoyaltyCard": "\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u0631\u062f\u0646\u06cc \u06a9\u0627\u0631\u062a\u06cc \u062f\u06b5\u0633\u06c6\u0632\u06cc",
