    "cardLaunchJourney": "\u06af\u06d5\u0634\u062a\u06cc \u062e\u0633\u062a\u0646\u06d5\u0628\u0627\u0632\u0627\u0695\u06cc \u06a9\u0627\u0631\u062a",
    "swipeOrUseTheArrowKeysToSeeEveryStage": "\u0628\u06c6 \u0628\u06cc\u0646\u06cc\u0646\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0642\u06c6\u0646\u0627\u063a\u06ce\u06a9 \u06a9\u0644\u06cc\u0644\u06cc \u062a\u06cc\u0631\u06d5\u06a9\u0627\u0646 \u0633\u0648\u0627\u06cc\u067e \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5",
    "studioSections": "\u0628\u06d5\u0634\u06d5\u06a9\u0627\u0646\u06cc \u0633\u062a\u06c6\u062f\u06cc\u06c6",
