    "next": "\u062f\u0627\u0647\u0627\u062a\u0648\u0648",
    "reviewTheSavedChangesBeforePublishingThemTheCurrentLiveCardIsUnchanged": "\u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0628\u06d5 \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5 \u0647\u06d5\u06b5\u06af\u06cc\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646\u062f\u0627 \u0628\u06a9\u06d5 \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u0628\u06b5\u0627\u0648\u06cc\u0627\u0646 \u0628\u06a9\u06d5\u06cc\u062a\u06d5\u0648\u06d5. \u0644\u0627\u06cc\u06a4 \u06a9\u0627\u0631\u062a\u06cc \u0626\u06ce\u0633\u062a\u0627 \u0646\u06d5\u06af\u06c6\u0695\u0627\u0648\u06d5.",
