    "managedInTheCardBuilderAndShownHereAsAReadOnlySummary": "\u0644\u06d5 Card Builder \u0628\u06d5\u0695\u06ce\u0648\u06d5\u062f\u06d5\u0628\u0631\u06ce\u062a \u0648 \u0644\u06ce\u0631\u06d5\u062f\u0627 \u0648\u06d5\u06a9 \u067e\u0648\u062e\u062a\u06d5\u06cc\u06d5\u06a9\u06cc \u062a\u06d5\u0646\u0647\u0627 \u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5 \u0646\u06cc\u0634\u0627\u0646 \u062f\u0631\u0627\u0648\u06d5.",
