    "savedChangesCannotBeEdited": "\u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5 \u0647\u06d5\u06b5\u06af\u06cc\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u0628\u06a9\u0631\u06ce\u0646.",
