    "yourLocalEditsArePreserved": "\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06cc\u06d5 \u0646\u0627\u0648\u062e\u06c6\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a \u067e\u0627\u0631\u06ce\u0632\u0631\u0627\u0648\u0646",
    "aNewerChangeWasSavedElsewhereWafloWillNotOverwriteEitherSetOfEditsAutomatically": "\u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u0646\u0648\u06ce\u062a\u0631 \u0644\u06d5 \u0634\u0648\u06ce\u0646\u06ce\u06a9\u06cc \u062a\u0631\u062f\u0627 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a \u06a9\u0631\u0627. Waflo \u0628\u06d5 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u0626\u06c6\u062a\u06c6\u0645\u0627\u062a\u06cc\u06a9\u06cc \u0647\u06cc\u0686 \u06a9\u0627\u0645 \u0644\u06d5 \u06a9\u06c6\u0645\u06d5\u06b5\u06d5 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0646\u0627\u0646\u0648\u0648\u0633\u06ce\u062a\u06d5\u0648\u06d5.",
    "keepACopyOfYourEditsThenLoadTheLatestCardOrDeliberatelyReapplyYours": "\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a\u0627\u0646 \u0647\u06d5\u06b5\u0628\u06af\u0631\u0646\u060c \u067e\u0627\u0634\u0627\u0646 \u0646\u0648\u06ce\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u062a \u0628\u0627\u0631\u0628\u06a9\u06d5\u0646 \u06cc\u0627\u0646 \u0628\u06d5 \u0626\u06d5\u0646\u0642\u06d5\u0633\u062a \u06a9\u0627\u0631\u062a\u06d5\u06a9\u06d5\u06cc \u062e\u06c6\u062a\u0627\u0646 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u0646\u06d5\u0648\u06d5.",
