    "downloadBackup": "\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a \u062f\u0627\u0628\u06d5\u0632\u06ce\u0646\u06d5",
    "loadLatestCard": "\u0646\u0648\u06ce\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u062a \u0628\u0627\u0631 \u0628\u06a9\u06d5",
    "reapplyMyEdits": "\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u0645 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5",
